//! The live views through a running console (the in-process forms of Zig's
//! `console_timeline_test.py`, `console_rankings_test.py`, `console_incident_geo_test.py`
//! and the live part of `console_challenge_test.py`): telemetry is injected into the data
//! plane's producers instead of being generated by traffic.

// Test code: a panic is how a failure is reported.
#![allow(clippy::unwrap_used)]

mod support;

use std::sync::Arc;
use std::time::{Duration, Instant};

use sibuna_console::Config;
use sibuna_console::GeoSlot;
use sibuna_console_protocol::client_family::{Browser, Os, status_slot};
use sibuna_console_protocol::codec::from_json;
use sibuna_console_protocol::{Role, StatsSnapshot, challenges, rankings, timeline};
use sibuna_core::incident_heads::ResponseState;
use sibuna_core::{Evidence, Incident};
use sibuna_geoip::{Loader, Provider};
use sibuna_store::challenge_metrics::{Algorithm, Cause};
use sibuna_store::telemetry::{ConsoleTelemetry, Outcome, Sample};
use support::{Harness, Response, Session};

/// A console whose telemetry and GeoIP slot the test holds, with a signed-in
/// administrator.
struct Live {
    harness: Harness,
    telemetry: Arc<ConsoleTelemetry>,
    geo: Arc<GeoSlot>,
    session: Session,
}

impl Live {
    fn start(name: &str) -> Live {
        let telemetry = Arc::new(ConsoleTelemetry::new());
        let shared = Arc::clone(&telemetry);
        let mut geo = None;
        let harness = Harness::start_with(name, Config::default(), |inputs| {
            inputs.telemetry = shared;
            geo = Some(Arc::clone(&inputs.geo));
        });
        let user = harness.create_user("admin", Role::Admin, false);
        let session = harness.sign_in(user, 1);
        Live { harness, telemetry, geo: geo.unwrap(), session }
    }

    fn get(&self, path: &str) -> Response {
        self.harness.get(path, &[("Cookie", &self.session.cookie)])
    }

    fn post(&self, path: &str, body: &str) -> Response {
        let cookie = ("Cookie", self.session.cookie.as_str());
        self.harness.post(path, &[cookie, ("X-Console-CSRF", &self.session.csrf)], body)
    }

    /// Polls `read` every 100 ms for at most ten seconds until it returns a value.
    fn until<T>(&self, what: &str, mut read: impl FnMut(&Live) -> Option<T>) -> T {
        let deadline = Instant::now() + Duration::from_secs(10);
        loop {
            if let Some(value) = read(self) {
                return value;
            }
            assert!(Instant::now() < deadline, "{what}");
            std::thread::sleep(Duration::from_millis(100));
        }
    }

    fn stats(&self) -> StatsSnapshot {
        let reply = self.get("/console/api/stats");
        assert_eq!(reply.status, 200, "{}", reply.text());
        from_json(&reply.body).unwrap()
    }
}

/// The outcome counts of a timeline page.
fn outcomes(page: &timeline::Page) -> u64 {
    page.rows.iter().map(|row| row.counts.requests().unwrap()).sum()
}

// console_timeline_test.py: live retained history is produced without any subscriber.
#[test]
fn the_timeline_retains_outcomes_without_subscribers() {
    let live = Live::start("timeline");
    let endpoint = "/console/api/timeline";
    assert_eq!(live.harness.post(endpoint, &[], "{}").status, 401);
    let cookie_only = [("Cookie", live.session.cookie.as_str())];
    assert_eq!(live.harness.post(endpoint, &cookie_only, "{}").status, 400);
    for query in [r#"{"limit":0}"#, r#"{"limit":17}"#, r#"{"before":1}"#, r#"{"unknown":1}"#] {
        let reply = live.post(endpoint, query);
        assert_eq!((reply.status, reply.code().as_str()), (400, "CONSOLE002"), "{query}");
    }
    for outcome in [Outcome::Admitted, Outcome::Challenged, Outcome::Denied, Outcome::Banned] {
        live.telemetry.count(outcome);
    }
    live.telemetry.count(Outcome::RateLimited);
    let page = live.until("the collector did not retain five outcomes", |live| {
        let reply = live.post(endpoint, r#"{"limit":16}"#);
        assert_eq!(reply.status, 200, "{}", reply.text());
        let page: timeline::Page = from_json(&reply.body).unwrap();
        (outcomes(&page) == 5).then_some(page)
    });
    assert_eq!((page.version, page.retention_seconds, page.node), (1, 3600, 1));
    assert_eq!(page.boot, "07".repeat(16));
    for row in &page.rows {
        assert!(row.end_ms - row.start_ms == row.observed_ms && row.observed_ms > 0);
    }
    let before = page.rows[0].sequence;
    let cursor = format!(
        r#"{{"before":{before},"boot":"{}","epoch":{},"limit":1}}"#,
        page.boot, page.epoch
    );
    let next = live.post(endpoint, &cursor);
    assert_eq!(next.status, 200);
    let next: timeline::Page = from_json(&next.body).unwrap();
    assert!(next.rows.iter().all(|row| row.sequence < before));
    let wrong = cursor.replace(&page.boot, &"f".repeat(32));
    let conflict = live.post(endpoint, &wrong);
    assert_eq!((conflict.status, conflict.code().as_str()), (409, "TIMELINE001"));
    assert!(conflict.text().contains("History changed. Reload the latest page."));
    let other = live.post(endpoint, r#"{"node":2}"#);
    assert_eq!((other.status, other.code().as_str()), (503, "CONSOLEPEERQUERY"));
    live.harness.stop();
}

// console_rankings_test.py: current-minute rankings come from samples and keep only the
// sampled path and the referring host.
#[test]
fn rankings_come_from_samples() {
    let live = Live::start("rankings");
    assert_eq!(live.harness.get("/console/api/rankings", &[]).status, 401);
    let now = support::unix_now();
    for index in 0..20u16 {
        let ip = format!("9.0.0.{index}");
        live.telemetry.push(
            Outcome::Admitted,
            &Sample {
                second: now,
                ip: ip.as_bytes(),
                path: b"/rank-review",
                referer: b"news.example.test",
                status: 200,
                os: Os::Linux as u8,
                browser: Browser::Firefox as u8,
            },
        );
    }
    let page = live.until("no ranking rows", |live| {
        let reply = live.get("/console/api/rankings");
        assert!(reply.status == 200 && reply.body.len() <= 16_384);
        let page: rankings::Page = from_json(&reply.body).unwrap();
        (page.retained_samples >= 20).then_some(page)
    });
    assert_eq!((page.sampling_probability.as_str(), page.counter_capacity), ("1/64", 256));
    assert!(page.rows.len() <= 12);
    assert!(page.minute_start <= page.snapshot_at && page.snapshot_at < page.minute_start + 60);
    let row = page.rows.iter().find(|row| row.key.as_str() == "/rank-review").unwrap();
    assert_eq!(row.encoding, rankings::Encoding::Utf8);
    assert!(row.estimate > 0 && row.error_bound == 0);
    assert!(page.retained_samples >= row.estimate);
    let host = page.referrers.iter().find(|row| row.key.as_str() == "news.example.test");
    assert!(host.unwrap().estimate >= 1);
    assert!(page.referrer_samples <= page.retained_samples);
    assert!(page.families.os[Os::Linux as usize] >= 20);
    assert!(page.families.browser[Browser::Firefox as usize] >= 20);
    assert_eq!(page.families.status[status_slot(200)], page.retained_samples);
    assert_eq!(page.families.status.iter().sum::<u64>(), page.retained_samples);
    assert_eq!(live.post("/console/api/rankings/query", r#"{"node":null}"#).status, 200);
    assert_eq!(live.post("/console/api/rankings/query", r#"{"node":1}"#).status, 200);
    let other = live.post("/console/api/rankings/query", r#"{"node":2}"#);
    assert_eq!((other.status, other.code().as_str()), (503, "CONSOLEPEERQUERY"));
    assert_eq!(live.post("/console/api/rankings/query", r#"{"x":1}"#).status, 400);
    live.harness.stop();
}

fn incident(client_ip: &str, now: u64) -> Incident<'_> {
    Incident {
        client_ip,
        user_agent: b"Mozilla/5.0",
        method: "GET",
        path: b"/__sibuna/honeypot",
        category: "honeypot",
        payload: b"",
        now,
        evidence: Evidence::default(),
        request_head: b"",
        response_head: b"",
        request_truncated: false,
        response_truncated: false,
        response_state: ResponseState::default(),
    }
}

// console_incident_geo_test.py (injected) and the collector half of
// console_incidents_test.zig: committed findings reach the geography exactly once, by
// their own time, without a subscriber; an import never relocates earlier findings.
#[test]
fn committed_findings_drive_the_incident_geography_exactly_once() {
    let live = Live::start("incident-geo");
    let now = support::unix_now();
    for index in 0..15 {
        live.harness.storage.record_incident(&incident(&format!("8.8.8.{}", index + 1), now));
    }
    let stats = live.until("the findings did not reach the geography", |live| {
        let stats = live.stats();
        stats.incident_geo.filter(|geo| geo.unknown == 15).map(|_| stats)
    });
    assert!(!stats.geoip_available);
    let geo = stats.incident_geo.unwrap();
    assert_eq!((geo.version, geo.dropped, geo.expired, geo.future), (1, 0, 0, 0));
    assert!(geo.started_at > 0);
    assert_eq!(stats.node, 1);
    let mut loader = Loader::new();
    loader.feed(b"8.8.0.0,8.8.255.255,US\n").unwrap();
    loader.end_file().unwrap();
    live.geo.restore(loader.finish(Provider::Dbip, "2026-09").unwrap(), 1, false);
    for index in 0..5 {
        live.harness.storage.record_incident(&incident(&format!("8.8.18.{}", index + 1), now));
    }
    let stats = live.until("the new findings got no country", |live| {
        let stats = live.stats();
        let geo = stats.incident_geo?;
        (geo.countries[0].code == 0x5553 && geo.countries[0].samples == 5).then_some(stats)
    });
    assert!(stats.geoip_available);
    // Earlier findings keep their original attribution, and nothing is counted twice.
    std::thread::sleep(Duration::from_millis(600));
    let geo = live.stats().incident_geo.unwrap();
    assert_eq!((geo.unknown, geo.countries[0].samples), (15, 5));
    live.harness.stop();
}

// challenge_routes.zig and console_challenge_test.py (live part): the funnel shows the
// counters of the chosen bin and the parameters last issued.
#[test]
fn the_challenge_funnel_reads_the_live_counters() {
    let live = Live::start("challenges");
    let metrics = &live.telemetry.challenges;
    metrics.issue(Algorithm::Hashcash, 16, 0);
    metrics.reject(Cause::MissingId);
    let reply = live.post("/console/api/challenges", r#"{"bin":null}"#);
    assert_eq!(reply.status, 200, "{}", reply.text());
    let snapshot: challenges::Snapshot = from_json(&reply.body).unwrap();
    assert_eq!((snapshot.issued, snapshot.rejected), (1, 1));
    assert_eq!(snapshot.causes[Cause::MissingId as usize], 1);
    assert_eq!(snapshot.selected, 8);
    assert_eq!(snapshot.last_issued.unwrap().parameter, 16);
    let chosen: challenges::Snapshot =
        from_json(&live.post("/console/api/challenges", r#"{"bin":133}"#).body).unwrap();
    assert_eq!(chosen.selected, 133);
    assert_eq!(live.post("/console/api/challenges", r#"{"bin":256}"#).status, 400);
    assert_eq!(live.post("/console/api/challenges", r#"{"other":1}"#).status, 400);
    live.harness.stop();
}

#[test]
fn statistics_describe_this_node_and_its_gauges() {
    let live = Live::start("stats");
    live.harness.node.bans.store(3, std::sync::atomic::Ordering::SeqCst);
    live.telemetry.count(Outcome::Admitted);
    let stats = live.until("no gauges", |live| {
        let stats = live.stats();
        (stats.active_bans == Some(3) && stats.uptime_ms > 0).then_some(stats)
    });
    assert_eq!((stats.node, stats.boot, stats.outcomes_version), (1, [7; 16], 1));
    assert_eq!((stats.requests, stats.admitted), (1, 1));
    assert_eq!(stats.cluster_health.unwrap().healthy, 1);
    assert_eq!(stats.sample_probability, "1/64");
    assert!(stats.minute_history.available);
    assert_eq!(stats.retention_failures, Some(0));
    if cfg!(target_os = "linux") {
        assert!(stats.rss_kib.unwrap() > 0);
    }
    assert!(stats.timestamp >= support::unix_now() - 5);
    live.harness.stop();
}
